#version 2
-- Duchess the Cat: a talking AI cat for any level (a global mod), a British Shorthair with opinions. She talks through
-- Proximity Comms' agents (the host's Koetama asks the host's language model) and, since its API 20, with the other AI
-- characters near her too - Mochi the Corgi above all. She does what she wants; ask nicely, or bribe her.
-- Files: cat_rig.lua (generated by tools/make_cat.py), cat_anim.lua (poses), cat_brain.lua (the host: her mind, treats,
-- the laser pointer, the agent), cat_view.lua (every machine: the model, sounds, the red dot, E to pet).
#include "cat_rig.lua"
#include "cat_anim.lua"
#include "cat_brain.lua"
#include "cat_view.lua"

function server.init() PudServerInit() end
function server.tick(dt) PudServerTick(dt) end
function server.update(dt) PudServerUpdate(dt) end
function server.postUpdate() PudServerPostUpdate() end

-- (clients: E on the cat)
function server.pudding_pet(p) PudPet(p) end

function client.init() PudClientInit() end
function client.tick(dt) PudClientTick(dt) end
function client.render(dt) PudClientRender(dt) end
function client.draw() PudClientDraw() end
